---@class ActivityChoosePayView : ViewBase
ActivityChoosePayView = class("ActivityChoosePayView", ViewBase)

function ActivityChoosePayView:initialize()
    ViewBase.initialize(self)
    ViewBase.RegisteAction(self, "ActivityChoosePayViewAction")
end

function ActivityChoosePayView:Awake()
    self:InitBtnFunc()
end

function ActivityChoosePayView:InitBtnFunc()
    CommonHelper:HButtonSetCallback("BtnPayOne", self.gameObject, function(data)
        self:OnChooseBtnClick("1")
    end)
    CommonHelper:HButtonSetCallback("BtnPayTwo", self.gameObject, function(data)
        self:OnChooseBtnClick("2")
    end)
    CommonHelper:HButtonSetCallback("BtnClose", self.gameObject, function(data)
        UIManager:Get():HidePersistentView("ActivityChoosePayView")
    end)
    CommonHelper:HButtonSetCallback("BtnClose2", self.gameObject, function(data)
        UIManager:Get():HidePersistentView("ActivityChoosePayView")
    end)
end

---@param msg SC_CreateSucc
function ActivityChoosePayView:InitViewInfo(msg)
    self.goodsId = msg.itemId
    self.CpOrderId = msg.cporderId
end

function ActivityChoosePayView:OnChooseBtnClick(payWay)
    ActivitySubsystem:Get():SendMsg_Purchase_BaXi_Shipment(self.goodsId, self.orderId, payWay)

    -- 下面这个是临时的假的测试
    if CommonHelper:GetSetChargeType() == 1 then
        if not UIManager:Get():IsPopViewShow("ActivityCashRegisterView") then
            UIManager:Get():OpenPopup("ActivityCashRegisterView", CanvasType.TopCanvas, "ActivityCashRegisterView",true,true)

            local msg = {url="http://www.protonjoy.com/pay.html",cpOrderId = self.CpOrderId,goodsId = self.goodsId}
            UINotify:Get():SendNotification(UINotifyEvent.ActivityCashRegisterView_OpenByUrl, msg)
        end
    end
    --UIManager:Get():ClosePopup()
    UIManager:Get():HidePersistentView("ActivityChoosePayView")
end


